import math

def sum_of_divisors(n):
    """Calculates sigma(n)"""
    if n == 1:
        return 1

    # Factorization using trial division
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    sigma = 1
    for p, a in factors.items():
        # Formula for sum of divisors: (p^(a+1) - 1) / (p - 1)
        sigma *= (p**(a + 1) - 1) // (p - 1)
    return sigma

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

